    for r in range(H):
        for c in range(W):
            if grid[r][c]==0 or (r,c) in seen: continue
            col=grid[r][c]; st=[(r,c)]; seen.add((r,c)); pix=[]
            while st:
                p=st.pop(); pix.append(p); pr,pc=p
                for q in ((pr-1,pc),(pr+1,pc),(pr,pc-1),(pr,pc+1)):
                    if 0<=q[0]<H and 0<=q[1]<W and q not in seen and grid[q[0]][q[1]]==col:
                        seen.add(q); st.append(q)
            comps.append((col,pix))
    def bb(pix):
        rs=[p[0] for p in pix]; cs=[p[1] for p in pix]
        return min(rs),min(cs),max(rs),max(cs)
    def region(pix):
        b=set(pix); out=set()
        q=[(r,c) for r in range(H) for c in range(W) if (r in (0,H-1) or c in (0,W-1)) and (r,c) not in b]
        out.update(q)
        while q:
            p=q.pop(); pr,pc=p
            for nr,nc in ((pr-1,pc),(pr+1,pc),(pr,pc-1),(pr,pc+1)):
                if 0<=nr<H and 0<=nc<W and (nr,nc) not in out and (nr,nc) not in b:
                    out.add((nr,nc)); q.append((nr,nc))
        return {(r,c) for r in range(H) for c in range(W) if (r,c) not in out and (r,c) not in b}
    conts=[]
    for col,pix in comps:
        if len(pix)>1 and region(pix):
            mnr,mnc,mxr,mxc=bb(pix)
            conts.append((col,pix,{(r,c) for r in range(mnr+1,mxr) for c in range(mnc+1,mxc)}))
    conts.sort(key=lambda t:(bb(t[1])[1],bb(t[1])[0],t[0]))
    row=[]
    for col,pix,reg in conts:
        cpx=set(pix)
        row += [col]*sum(1 for (r,c) in reg if grid[r][c]!=0 and (r,c) not in cpx)
    return [row]

def transform(grid):
